   167	import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
   168	import type { CachedTrashState } from '../lib/cached-trash';
   169	import type { ConversationRef, MailClient } from '../lib/ipc/client';
   170	import { toMailError } from '../lib/ipc/client';
   171	const props = defineProps<{ client: MailClient; accountId: string; state: CachedTrashState }>();
   172	const emit = defineEmits<{ open: [target: ConversationRef] }>();
   173	const busy = ref(false);
   174	const list = ref<HTMLElement | null>(null);
   175	let alive = true;
   176	onBeforeUnmount(() => { alive = false; });
   177	async function load(reset = false): Promise<void> {
   178	  if (busy.value) return;
   179	  busy.value = true;
   180	  props.state.error = null;
   181	  try {
   182	    const page = await props.client.listCachedTrash({ accountId: props.accountId, limit: 50, cursor: reset ? null : props.state.cursor });
   183	    if (!alive) return;
   184	    props.state.rows = reset ? page.conversations : [...props.state.rows, ...page.conversations.filter(row => !props.state.rows.some(old => old.ref.accountId === row.ref.accountId && old.ref.conversationId === row.ref.conversationId))];
   185	    props.state.cursor = page.nextCursor;
   186	    props.state.loaded = true;
   187	  } catch (error) { if (alive) props.state.error = toMailError(error); }
   188	  finally { if (alive) busy.value = false; }
   189	}
   190	function open(target: ConversationRef): void {
   191	  props.state.focusedId = target.conversationId;
   192	  emit('open', { ...target });
   193	}
   194	onMounted(async () => {
   195	  if (!props.state.loaded) await load(true);
   196	  await nextTick();
   197	  const buttons = list.value?.querySelectorAll<HTMLButtonElement>('button');
   198	  [...buttons ?? []].find(button => button.dataset.id === props.state.focusedId)?.focus({ preventScroll: true });
   199	  if (list.value) list.value.scrollTop = props.state.scrollTop;
   200	});
   201	</script>
   202	
   203	<template>
   204	  <section aria-label="Cached Trash browsing" :aria-busy="busy">
   205	    <p>Known cached Trash only — not your complete Gmail Trash. Reading does not mark mail read.</p>
   206	    <p>Loaded local snapshot — refresh to see later cache changes.</p>
   207	    <p v-if="state.loaded" role="status">{{ state.rows.length }} cached conversations loaded. Total unknown.</p>
   208	    <p>Trash is not Done. Move to Trash, Recover, permanent delete and Empty Trash are not available in this build. Use your provider client for recovery.</p>
   209	    <button type="button" :disabled="busy" @click="load(true)">Refresh cached Trash</button>
   210	    <p v-if="state.error" role="alert">Could not load cached Trash ({{ state.error.kind }}). <button type="button" :disabled="busy" @click="load(!state.loaded)">Retry</button></p>
   211	    <p v-if="busy" role="status">Loading cached Trash…</p>
   212	    <p v-else-if="state.loaded && !state.rows.length">No known cached Trash conversations. This does not mean your Gmail Trash is empty.</p>
   213	    <ul ref="list" class="cached-trash-list" aria-label="Cached Trash conversations" @scroll="state.scrollTop = list?.scrollTop ?? 0">
