   215	        <button type="button" :data-id="row.ref.conversationId" @click="open(row.ref)">{{ row.subject || '(No subject)' }}</button>
   216	        <span>{{ row.primaryCorrespondent?.mailbox }}</span>
   217	      </li>
   218	    </ul>
