  1	<script setup lang="ts">
  2	import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
  3	import type { CancelReminder, ConversationRef, MailClient, PutReminder, Reminder, ReminderCondition } from '../lib/ipc/client';
  4	import { toMailError } from '../lib/ipc/client';
  5	import FullDate from './FullDate.vue';
  6	const props = defineProps<{ client: MailClient; target: ConversationRef | null; initialDestination?: 'pending' | 'returned' | 'history' }>();
  7	const emit = defineEmits<{ open: [target: ConversationRef]; destinationChange: [destination: 'pending' | 'returned' | 'history'] }>();
  8	const rows = ref<Reminder[]>([]);
  9	const error = ref('');
 10	const preparationError = ref('');
 11	const preparationTarget = ref<ConversationRef | null>(null);
 12	const busy = ref(false);
 13	const loading = ref(true);
 14	const source = ref<{ conversation: ConversationRef; sourceMessageId: string; revision: number | null } | null>(null);
 15	const due = ref('');
 16	const someday = ref(false);
 17	const condition = ref<ReminderCondition>('if_no_reply');
 18	const destination = ref<'pending' | 'returned' | 'history'>(props.initialDestination ?? 'pending');
 19	watch(destination, value => emit('destinationChange', value));
 20	let retry: { action: () => Promise<unknown>; command?: PutReminder } | null = null;
 21	let alive = true;
 22	let generation = 0;
 23	let editorGeneration = 0;
 24	let unsubscribe: (() => void) | undefined;
 25	const displayed = computed(() => rows.value.filter(r => destination.value === 'returned' ? r.phase === 'returned' : destination.value === 'history' ? ['suppressed', 'cancelled'].includes(r.phase) : !['returned', 'suppressed', 'cancelled'].includes(r.phase)));
 26	async function refresh() {
 27	  const token = ++generation;
 28	  try {
 29	    const result = await props.client.reminders!.list();
 30	    if (alive && token === generation) { rows.value = result; loading.value = false; }
 31	  } catch { if (alive && token === generation) { error.value = 'Could not load local reminders. Retry refresh.'; loading.value = false; } }
 32	}
 33	async function run(action: () => Promise<unknown>, command?: PutReminder) {
 34	  if (busy.value) return;
 35	  const token = editorGeneration;
 36	  // Retain both the exact payload and its validation context after a lost ACK.
 37	  busy.value = true; error.value = ''; retry = { action, command };
 38	  try { await action(); if (alive && token === editorGeneration) { retry = null; source.value = null; await refresh(); } }
 39	  catch (raw) {
 40	    if (alive && token === editorGeneration) {
 41	      const failure = toMailError(raw);
 42	      if (failure.kind === 'invalid_request' && failure.field === 'dueAt') {
 43	        retry = null;
 44	        error.value = 'Choose a future RFC3339 time with seconds and Z or a numeric timezone offset. Local times and leap seconds are not supported.';
 45	      } else if (failure.kind === 'invalid_request' && failure.field === 'sourceMessageId' && command?.expectedRevision === null) {
 46	        retry = null; source.value = null;
 47	        preparationTarget.value = { ...command.conversation };
 48	        preparationError.value = 'This conversation has a newer message. Refresh the source, review it, then schedule again.';
 49	      } else if (failure.kind === 'invalid_request' || failure.kind === 'not_found') {
 50	        retry = null; source.value = null;
 51	        error.value = 'This target or revision is no longer actionable. Refresh and choose the current reminder before editing.';
 52	        await refresh();
 53	      } else {
 54	        error.value = 'Reminder change was not acknowledged. Retry the exact request, or refresh to inspect durable state. Stale revisions require refresh before editing.';
 55	      }
 56	    }
 57	  }
 58	  finally { if (alive && token === editorGeneration) busy.value = false; }
 59	}
 60	async function prepare(target: ConversationRef) {
 61	  if (busy.value || retry) return;
 62	  const token = ++editorGeneration;
 63	  const requested = { ...target };
 64	  preparationTarget.value = requested;
 65	  source.value = null;
 66	  busy.value = true;
 67	  try {
 68	    const conversation = await props.client.getConversation(requested);
 69	    if (!alive || token !== editorGeneration) return;
 70	    const latest = conversation.messages.at(-1);
 71	    if (conversation.ref.accountId !== requested.accountId || conversation.ref.conversationId !== requested.conversationId || !latest) {
 72	      preparationError.value = 'No current source message is available for this conversation. Retry preparation after it is available.';
 73	      return;
 74	    }
 75	    if (conversation.retainedSnapshotAt || conversation.contextComplete === false) {
 76	      preparationError.value = 'This conversation is retained or incomplete. A current conversation is required; retry preparation after it is available.';
 77	      return;
 78	    }
 79	    source.value = { conversation: requested, sourceMessageId: latest.id, revision: null };
 80	    preparationTarget.value = null;
 81	    preparationError.value = '';
 82	  } catch { if (alive && token === editorGeneration) preparationError.value = 'Could not load the current source message. Retry preparation for this conversation.'; }
 83	  finally { if (alive && token === editorGeneration) busy.value = false; }
 84	}
 85	function dismissPicker() {
 86	  editorGeneration++;
 87	  busy.value = false; retry = null; source.value = null;
 88	  preparationTarget.value = null; preparationError.value = '';
 89	}
 90	watch(() => [props.client, props.target?.accountId, props.target?.conversationId], () => {
 91	  dismissPicker();
 92	  if (props.target) void prepare(props.target);
 93	});
 94	function reschedule(r: Reminder) {
 95	  dismissPicker(); error.value = '';
 96	  source.value = { conversation: r.conversation, sourceMessageId: r.sourceMessageId, revision: r.revision };
 97	  due.value = r.dueAt ?? ''; someday.value = r.dueAt === null; condition.value = r.condition;
 98	}
 99	function submit() {
100	  if (!source.value || retry) return;
101	  const command: PutReminder = { conversation: source.value.conversation, sourceMessageId: source.value.sourceMessageId, expectedRevision: source.value.revision, dueAt: someday.value ? null : due.value, condition: condition.value, requestId: crypto.randomUUID() };
102	  void run(() => props.client.reminders!.put(command), command);
103	}
104	function cancel(r: Reminder) {
105	  const command: CancelReminder = { conversation: r.conversation, expectedRevision: r.revision, requestId: crypto.randomUUID() };
106	  void run(() => props.client.reminders!.cancel(command));
107	}
108	onMounted(async () => {
109	  const token = editorGeneration;
110	  try {
111	    const stop = await props.client.subscribe(() => { void refresh(); });
112	    if (!alive) { stop(); return; }
113	    unsubscribe = stop;
114	  } catch { if (alive) error.value = 'Live updates unavailable. Refresh to inspect progress.'; }
115	  await refresh();
116	  if (alive && token === editorGeneration && props.target) await prepare(props.target);
117	});
118	onBeforeUnmount(() => { alive = false; generation++; editorGeneration++; unsubscribe?.(); });
119	</script>
120	
121	<template>
122	  <section class="reminders-panel" aria-label="Desktop-local reminders">
123	    <p role="note">Synthetic fixture only · This device, while running. Overdue work reconciles on launch. No execution while fully quit or on other devices.</p>
124	    <p>New incoming mail stays in Inbox. Return and Cancel restore only the original inbox messages; neither marks mail read.</p>
125	    <p v-if="error" role="alert">{{ error }}</p>
126	    <p v-if="preparationError" role="alert">{{ preparationError }}</p>
127	    <button v-if="preparationTarget" type="button" :disabled="busy || !!retry" @click="prepare(preparationTarget)">{{ busy ? 'Preparing current source…' : 'Retry preparation / refresh source' }}</button>
128	    <button type="button" :disabled="busy" @click="retry ? run(retry.action, retry.command) : refresh()">{{ retry ? 'Retry exact request' : 'Refresh reminders' }}</button>
129	    <button v-if="retry" type="button" :disabled="busy" @click="dismissPicker(); error = ''; refresh()">Inspect durable state</button>
130	    <form v-if="source" @submit.prevent="submit">
131	      <h3>{{ source.revision === null ? 'Remind me' : 'Reschedule' }}</h3>
132	      <p>{{ source.conversation.conversationId }} · source {{ source.sourceMessageId }}</p>
133	      <fieldset :disabled="busy || !!retry">
134	        <label><input v-model="someday" type="checkbox"> Someday — no automatic return</label>
135	        <label v-if="!someday">Time with timezone offset
136	          <input v-model="due" required type="text" placeholder="2030-11-03T09:00:00-05:00" aria-describedby="reminder-time-help">
137	        </label>
138	        <p id="reminder-time-help">Use RFC3339 with Z or a numeric offset. No ambiguous local times or automatic DST adjustment.</p>
139	        <label>Return condition
